import sys

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, m = map(int, input[ptr:ptr+2])
        ptr +=2
        perms = []
        for __ in range(n):
            perm = list(map(int, input[ptr:ptr+m]))
            perms.append(perm)
            ptr += m
        res = []
        for i in range(n):
            max_beauty = 0
            for j in range(n):
                beauty = 0
                for k in range(1, m+1):
                    if perms[i][k-1] == k:
                        beauty += 1
                    else:
                        break
                if beauty > max_beauty:
                    max_beauty = beauty
            res.append(max_beauty)
        print(' '.join(map(str, res)))

solve()
